# /workspace/trading/chain.py
import json
import os
import urllib.request

RPC = os.getenv("RH_RPC", "https://rpc.mainnet.chain.robinhood.com")
EXPLORER_API = "https://robinhoodchain.blockscout.com/api/v2"
CHAIN_ID = 4663


def _post(url, payload):
    req = urllib.request.Request(
        url,
        json.dumps(payload).encode(),
        {"Content-Type": "application/json", "User-Agent": "rh-agent/1.0"},
    )
    with urllib.request.urlopen(req, timeout=20) as r:
        return json.load(r)


def rpc(method, params):
    out = _post(RPC, {"jsonrpc": "2.0", "id": 1, "method": method, "params": params})
    if "error" in out:
        raise RuntimeError(out["error"])
    return out["result"]


def get_json(url):
    req = urllib.request.Request(url, headers={"User-Agent": "rh-agent/1.0"})
    with urllib.request.urlopen(req, timeout=20) as r:
        return json.load(r)


def check_chain():
    got = int(rpc("eth_chainId", []), 16)
    if got != CHAIN_ID:
        raise SystemExit(f"Wrong chain: got {got}, expected {CHAIN_ID}")


def call(to, data):
    return rpc("eth_call", [{"to": to, "data": data}, "latest"])


def read_uint(to, selector, arg=""):
    return int(call(to, selector + arg), 16)


def read_string(to, selector):
    raw = call(to, selector)[2:]
    if len(raw) == 64:  # old tokens return bytes32 instead of a string
        return bytes.fromhex(raw).rstrip(b"\x00").decode("utf-8", "ignore")
    offset = int(raw[:64], 16) * 2
    size = int(raw[offset:offset + 64], 16) * 2
    return bytes.fromhex(raw[offset + 64: offset + 64 + size]).decode("utf-8", "ignore")


def pad(address):
    return address[2:].lower().zfill(64)
