# /workspace/trading/risk_check.py
import csv
import json
import re
import sys
from pathlib import Path

from chain import EXPLORER_API, call, get_json, pad, read_string, read_uint
from scanner import BASE_ADDR

HOME = Path("/workspace/trading")
RULES = json.loads((HOME / "rules.json").read_text())
PAIRS = HOME / "pairs.csv"
CHECKED = HOME / "checked.json"
PASSED = HOME / "candidates.jsonl"
DEAD = "0x000000000000000000000000000000000000dead"
MAX_TRIES = 4  # fresh pools often have zero liquidity for a few minutes


def clean(text, n=24):
    """Token names come from strangers. Keep only harmless characters."""
    return re.sub(r"[^A-Za-z0-9 $._-]", "", text or "")[:n] or "unnamed"


def pool_depth(pool, base):
    decimals = read_uint(BASE_ADDR[base], "0x313ce567")
    return read_uint(BASE_ADDR[base], "0x70a08231", pad(pool)) / 10 ** decimals


def owner_status(token):
    try:
        return "renounced" if int(call(token, "0x8da5cb5b"), 16) == 0 else "active"
    except Exception:
        return "none"  # no owner() function at all, usually fine


def top10_share(token, pool, supply):
    data = get_json(f"{EXPLORER_API}/tokens/{token}/holders")
    skip = {pool.lower(), DEAD}
    holders = [h for h in data.get("items", []) if h["address"]["hash"].lower() not in skip]
    held = sum(int(h["value"]) for h in holders[:10])
    return 100 * held / supply if supply else 100.0


def is_verified(token):
    try:
        info = get_json(f"{EXPLORER_API}/smart-contracts/{token}")
        return bool(info.get("is_verified") or info.get("is_fully_verified") or info.get("source_code"))
    except Exception:
        return False


def check(row):
    token, pool, base = row["meme"], row["pool"], row["base"]
    try:
        name = clean(read_string(token, "0x06fdde03"))
        symbol = clean(read_string(token, "0x95d89b41"), 12)
        supply = read_uint(token, "0x18160ddd")
        depth = pool_depth(pool, base)
        share = top10_share(token, pool, supply)
    except Exception as e:
        return {"token": token, "pool": pool, "pass": False, "empty": False,
                "why": [f"unreadable: {type(e).__name__}"]}

    why = []
    need = RULES["min_weth_in_pool"] if base == "WETH" else RULES["min_usdg_in_pool"]
    if depth < need:
        why.append(f"thin pool: {depth:.2f} {base}")
    if share > RULES["max_top10_holder_pct"]:
        why.append(f"top 10 wallets hold {share:.0f}%")
    if RULES["require_verified_contract"] and not is_verified(token):
        why.append("contract not verified")
    owner = owner_status(token)
    if RULES["require_renounced_owner"] and owner == "active":
        why.append("owner can still act")

    return {"token": token, "pool": pool, "name": name, "symbol": symbol, "base": base,
            "pool_depth": round(depth, 2), "top10_pct": round(share, 1), "owner": owner,
            "pass": not why, "empty": depth == 0, "why": why}


def run_new():
    tries = json.loads(CHECKED.read_text()) if CHECKED.exists() else {}
    rows = list(csv.DictReader(PAIRS.open())) if PAIRS.exists() else []
    passed, rejected = [], 0
    for row in rows:
        n = tries.get(row["pool"], 0)
        if n >= MAX_TRIES or tries.get(row["pool"]) == "done":
            continue
        res = check(row)
        if res["pass"]:
            passed.append(res)
            with PASSED.open("a") as f:
                f.write(json.dumps(res) + "\n")
            tries[row["pool"]] = "done"
        elif res["empty"] and n + 1 < MAX_TRIES:
            tries[row["pool"]] = n + 1  # no liquidity yet, look again next run
        else:
            rejected += 1
            tries[row["pool"]] = "done"
    CHECKED.write_text(json.dumps(tries))
    print(f"{len(passed)} passed, {rejected} rejected")
    for p in passed:
        print(f'PASS {p["symbol"]} token {p["token"]} pool {p["pool"]} '
              f'depth {p["pool_depth"]} {p["base"]} top10 {p["top10_pct"]}%')


if __name__ == "__main__":
    if len(sys.argv) == 2 and sys.argv[1] == "--new":
        run_new()
    elif len(sys.argv) == 5 and sys.argv[1] == "one":
        print(json.dumps(check({"meme": sys.argv[2], "pool": sys.argv[3], "base": sys.argv[4]}), indent=2))
    else:
        print("usage: risk_check.py --new | risk_check.py one TOKEN POOL WETH|USDG")
